import{S as n,o as t,c as h,a9 as k,B as l}from"./chunks/framework.DxG24V0C.js";const p="/agentsrc/images/codex/05-hero.png",e="/agentsrc/images/codex/05-states.png",r="/agentsrc/images/codex/05-tools.png",d="/agentsrc/images/codex/05-csv.png",F=JSON.parse('{"title":"多 Agent 编排架构","description":"","frontmatter":{},"headers":[],"relativePath":"codex/05-multi-agents.md","filePath":"codex/05-multi-agents.md","lastUpdated":1788319991000}'),E={name:"codex/05-multi-agents.md"},c=Object.assign(E,{setup(g){const i=[{question:"Codex 多 Agent 系统的 AgentPath 为什么采用类似文件系统的路径设计（如 /root/researcher/worker）？",options:["统一用短标识符作为路径可使序列化传输占用更少网络带宽","支持绝对路径相对路径和特殊路径使寻址方式灵活且自然","直接将文件系统的挂载路径映射为子 Agent 全局标识符","为满足 JSON Schema 标准序列化格式对路径字段的规范约束"],correct:1,explanation:"AgentPath 设计为类似文件系统的树状路径：绝对路径（/root/researcher 以 / 开头）、相对路径（worker 相对当前 agent）、特殊路径（/root 根 agent）。子 agent 不需要知道父 agent 的全局路径就能寻址，通信非常自然。"},{question:"V2 中 send_message 和 followup_task 的核心区别是什么？",options:["send_message 仅允许由父 Agent 向子 Agent 方向发送消息","send_message 使用 QueueOnly 模式 followup_task 使用 TriggerTurn","send_message 对单条消息内容的长度施加了严格的字符限制","两者在底层实现上功能完全一致仅对外暴露的工具名不同"],correct:1,explanation:"这个区分是实现 map-reduce 模式的关键：父 agent 先用 send_message 批量发消息给多个子 agent（只入队不触发 turn），再用 followup_task 统一唤醒它们并行执行，最后 wait_agent 收集结果。"},{question:"为什么 V2 移除了深度限制（V1 有），改为依赖 agent_max_threads（并发数限制）？",options:["V2 架构设计限制子 Agent 不能再递归调用 spawn_agent 工具","V2 更信任 Agent 自身判断能力用并发上限替代深度限制","V2 尚未实现深度限制检查功能将在后续版本中补全","深度限制逻辑在 V2 中改由 OpenAI 服务端 API 统一控制"],correct:1,explanation:"V2 中 collab_tools_enabled 总是返回 true，不检查深度。依赖 agent 自己的判断和 agent_max_threads（并发数上限）来防止递归失控，体现了 V2 对 agent 能力的信任。"},{question:"Codex 的 CSV 批处理模式（spawn_agents_on_csv）中，默认并发上限和最大并发分别是多少？为什么？",options:["默认 4 并行执行上限而最大并发配置上限设为 16","默认 16 并发且最大 64 通过槽位控制防止系统资源耗尽","默认 1 串行执行且不允许配置超过 10 的并发上限","不设置任何并发限制各 CSV 行同时全量并行 spawn 子 Agent"],correct:1,explanation:"默认 16 并发（DEFAULT_AGENT_JOB_CONCURRENCY），最大 64（MAX_AGENT_JOB_CONCURRENCY）。并发槽位控制让大量 CSV 行分批 spawn worker agent，避免一次性创建上千个 agent 导致资源耗尽。"}];return(y,s)=>{const a=n("Quiz");return t(),h("div",null,[s[0]||(s[0]=k("",145)),l(a,{questions:i})])}}});export{F as __pageData,c as default};
